import copy
import hashlib
import json
from pathlib import Path

ROOT = Path('/workspace/scratch/bfccb8494ba0')
OUT = ROOT / 'round27-integration-P-source-review'
P = '411336a666df78cfc96172b889f9109c3e84c295'
TREE = 'daca3f888be69ef81cb465a892deebefeaf74094'
PARENTS = ['34dc4e14dc96d077eae6173ab6885370323eff3f', '065f5ab5da1bc5de74cbd3e4c360b51e09200687']

def read(path):
    return json.loads(path.read_text())

def sha(raw):
    return hashlib.sha256(raw).hexdigest()

def oid(kind, raw):
    return hashlib.sha1(kind.encode() + b' ' + str(len(raw)).encode() + b'\0' + raw).hexdigest()

def tree_oid(entries):
    def key(row):
        return row['path'].encode() + (b'/' if row['type'] == 'tree' else b'')
    raw = b''.join(row['mode'].lstrip('0').encode() + b' ' + row['path'].encode() + b'\0' + bytes.fromhex(row['sha']) for row in sorted(entries, key=key))
    return oid('tree', raw)

prior = read(ROOT / 'round25-GCW3-binding/inputs/canonical.json')
donor = read(ROOT / 'round27-PR196-review/canonical.json')
main = read(ROOT / 'round27-PR196-review/seed-main-reviewed-source-registry-v15.json')
request = read(ROOT / 'round27-PR196-review/candidate-11-leaf-create-tree-request.json')
commit = read(OUT / 'official/actual-P-commit.json')
assert commit['sha'] == P and commit['tree']['sha'] == TREE
assert [row['sha'] for row in commit['parents']] == PARENTS
root = read(OUT / 'official/actual-P-root-tree.json')
assert root['sha'] == TREE and tree_oid(root['tree']) == TREE
actual = {x['path']: x for x in root['tree'] if x['type'] == 'blob'}
checked_trees = [{'path': '', 'sha': TREE}]
for prefix, filename in [('.github', 'github'), ('crates', 'crates'), ('scripts', 'scripts'), ('tests', 'tests')]:
    data = read(OUT / ('official/actual-P-' + filename + '-tree.json'))
    assert data.get('truncated') is False
    assert data['sha'] == next(x['sha'] for x in root['tree'] if x['path'] == prefix)
    groups = {'': []}
    expected = {'': data['sha']}
    for row in data['tree']:
        parent, _, basename = row['path'].rpartition('/')
        entry = dict(row, path=basename)
        groups.setdefault(parent, []).append(entry)
        if row['type'] == 'tree':
            expected[row['path']] = row['sha']
        else:
            actual[prefix + '/' + row['path']] = row
    assert set(groups) == set(expected)
    for path, entries in groups.items():
        assert tree_oid(entries) == expected[path], (prefix, path)
        checked_trees.append({'path': prefix + ('/' + path if path else ''), 'sha': expected[path]})

compare = read(OUT / 'official/actual-P-versus-GCW3-compare.json')
assert compare['base_commit']['sha'] == PARENTS[0]
assert compare['commits'][-1]['sha'] == P
expected_changes = {row['path']: row for row in request['tree_elements']}
assert len(compare['files']) == len(expected_changes) == 11
assert set(x['filename'] for x in compare['files']) == set(expected_changes)
for row in compare['files']:
    assert row['sha'] == expected_changes[row['filename']]['sha']
assert sorted(row['status'] for row in compare['files']) == ['added'] * 2 + ['modified'] * 9

complete = copy.deepcopy(prior['complete_inputs'])
validation = copy.deepcopy(prior['validation_inputs'])
delta = copy.deepcopy(prior['paths'])
inventory = copy.deepcopy(prior['actual_input_mode_blob_inventory'])
proof = []
for path, entry in expected_changes.items():
    if path.startswith('artifacts/'):
        raw = (ROOT / 'round27-PR196-review/canonical.json').read_bytes()
        assert oid('blob', raw) == entry['sha']
        continue
    domain = 'complete_inputs' if path.startswith('crates/') else 'validation_inputs'
    assert prior[domain].get(path) == main[domain].get(path), ('nonoverlap', path)
    if path == 'crates/cc-index/src/sparse_actions_tests.rs':
        local = OUT / 'sparse_actions_tests.rs'
    elif path.startswith('crates/cc-index/'):
        local = ROOT / 'round27-PR196-scan-review/source' / path
    else:
        local = ROOT / 'round27-PR196-installer-archive-review/source' / path
    raw = local.read_bytes()
    digest = sha(raw)
    git_blob = oid('blob', raw)
    assert git_blob == entry['sha'] == actual[path]['sha']
    assert len(raw) == actual[path]['size']
    assert actual[path]['mode'] == entry['mode'] == '100644' and actual[path]['type'] == 'blob'
    assert digest == donor[domain][path]
    (complete if domain == 'complete_inputs' else validation)[path] = digest
    inventory[path] = {'mode': actual[path]['mode'], 'sha': git_blob, 'sha256': digest, 'size': len(raw), 'type': 'blob'}
    if domain == 'complete_inputs':
        before = donor['paths'][path]['before_sha256']
        if path in delta:
            assert delta[path]['before_sha256'] == before
        delta[path] = {'before_sha256': before, 'sha256': digest}
    proof.append({'path': path, 'domain': domain, 'before_GCW3_sha256': prior[domain].get(path), 'before_PR196_main_sha256': main[domain].get(path), 'nonoverlap': True, 'after': inventory[path], 'source_bytes': str(local)})

product_paths = {p for p in actual if p.startswith('crates/') or p in {'Cargo.toml', 'Cargo.lock'}}
excluded = {'scripts/verify_reviewed_source_v15.py', 'scripts/reviewed-source-registry-v15.json', '.github/workflows/ci.yml'}
validation_paths = {p for p in actual if p.startswith(('scripts/', '.github/workflows/', 'tests/source_integrity/')) and p not in excluded and not ('__pycache__' in Path(p).parts and p.endswith('.pyc'))}
assert product_paths == set(complete) and validation_paths == set(validation)
assert set(inventory) == product_paths | validation_paths
assert (len(complete), len(delta), len(validation), len(inventory)) == (1096, 78, 146, 1242)
for p, row in inventory.items():
    assert {key: row[key] for key in ('mode', 'type', 'sha', 'size')} == {key: actual[p][key] for key in ('mode', 'type', 'sha', 'size')}, p
    assert row['sha256'] == (complete | validation)[p]
for p, row in delta.items():
    assert set(row) == {'before_sha256', 'sha256'}
    assert row['sha256'] == complete[p] and row['before_sha256'] != row['sha256']
assert set(prior['complete_inputs']) <= set(complete)
assert set(prior['validation_inputs']) == set(validation)
assert sum(prior['complete_inputs'].get(p) != v for p, v in complete.items()) == 8
assert sum(prior['validation_inputs'].get(p) != v for p, v in validation.items()) == 2
seed = {}
for p in sorted(excluded):
    if p.startswith('scripts/'):
        raw = (ROOT / 'round25-GCW3-binding/generated' / p).read_bytes()
        assert oid('blob', raw) == actual[p]['sha']
        seed[p] = {'bytes': len(raw), 'sha256': sha(raw), 'git_blob': actual[p]['sha']}
    else:
        assert actual[p]['sha'] == '8c7325eb88b791f909e72c4b6c79b417185e4386'
        seed[p] = {'bytes': actual[p]['size'], 'git_blob': actual[p]['sha']}
assert all(p not in {x['filename'] for x in compare['files']} for p in excluded)
result = {'schema_version': 1, 'verdict': 'actual_P_complete_domains_and_disjoint_donor_composition_verified', 'source': P, 'tree': TREE, 'ordered_parents': PARENTS, 'counts': {'product': len(complete), 'BASE_delta': len(delta), 'validation': len(validation), 'source_and_validation': len(inventory)}, 'actual_diff': [{'path': x['filename'], 'status': x['status'], 'git_blob': x['sha']} for x in compare['files']], 'changed_source_byte_proof': proof, 'checked_Git_tree_objects': checked_trees, 'unchanged_binding_and_CI': seed, 'complete_inputs': dict(sorted(complete.items())), 'paths': dict(sorted(delta.items())), 'validation_inputs': dict(sorted(validation.items())), 'actual_input_mode_blob_inventory': dict(sorted(inventory.items())), 'method_boundary': 'Official current-P root plus non-truncated recursive metadata for exactly crates/scripts/tests/.github, with every supplied tree object reconstructed. Changed blob bytes directly recomputed. Unchanged SHA256 values inherited only when actual mode/type/Git blob/size exactly match the previously independently accepted GCW3 inventory. BASE before digests and membership follow the accepted complete GCW3 delta plus donor delta, with matching overlapping before values; no historical execution or all-history re-review is claimed.', 'no_product_or_validator_execution': True}
(OUT / 'actual-P-complete-domain-review.json').write_text(json.dumps(result, indent=2, ensure_ascii=False) + '\n')
print(json.dumps({'verdict': result['verdict'], 'source': P, 'counts': result['counts'], 'tree_objects_recomputed': len(checked_trees), 'changed_source_bytes_checked': len(proof), 'runtime': 'not_run'}, sort_keys=True))
